-- OPTIONAL sample data (non-sensitive). First register a user named "demo" in the app, then run this script.
-- Doses are generated by the app when you log in. Schedules start "now", so no fake missed doses appear.
USE smart_medicine_db;
INSERT INTO medicines (user_id, name, dosage, frequency, start_date, end_date, notes)
  SELECT id, 'Vitamin D', '1 tablet', 'ONCE_DAILY', CURRENT_DATE, NULL, 'After breakfast' FROM users WHERE username = 'demo';
INSERT INTO medicine_schedules (medicine_id, reminder_time, created_at)
  SELECT LAST_INSERT_ID(), '08:00:00', NOW();
INSERT INTO medicines (user_id, name, dosage, frequency, start_date, end_date, notes)
  SELECT id, 'Paracetamol', '5 ml', 'TWICE_DAILY', CURRENT_DATE, DATE_ADD(CURRENT_DATE, INTERVAL 7 DAY), 'Only if needed' FROM users WHERE username = 'demo';
SET @pid = LAST_INSERT_ID();
INSERT INTO medicine_schedules (medicine_id, reminder_time, created_at) VALUES (@pid, '09:00:00', NOW()), (@pid, '21:00:00', NOW());
